(function () {
  // Minimal loader: inject Slick from CDN if not already present
  try {
    if (typeof jQuery === 'undefined') {
      console.warn('Slick loader: jQuery not found — ensure jQuery is loaded before initializing Slick.');
      return;
    }
    if (typeof jQuery.fn === 'object' && typeof jQuery.fn.slick === 'function') {
      // already loaded
      return;
    }
    var script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/slick-carousel@1.8.1/slick/slick.min.js';
    script.async = true;
    document.head.appendChild(script);
  } catch (e) {
    console.error('Slick loader error', e);
  }
})();

